from langgraph.types import Command, interrupt

def human_approval_node(state: TriageState) -> Command:
    # Keep node purely focused on review payload -> interrupt -> route!
    reviewer_decision = interrupt({
        "ticket_id": state["ticket_id"],
        "category": state["category"],
        "draft_reply": state["draft_reply"],
        "cited_doc_ids": state["cited_doc_ids"],
    })
    if reviewer_decision.get("approved") is True:
        edited = reviewer_decision.get("edited_reply") or state["draft_reply"]
        return Command(update={"approved": True, "draft_reply": edited}, goto="send_reply")
    return Command(update={"approved": False}, goto="escalate_manual")

from langgraph.types import Command

def submit_approval_decision(graph, ticket_id: str, payload: dict) -> dict:
    cfg = {"configurable": {"thread_id": f"ticket_{ticket_id}"}}
    snapshot = graph.get_state(cfg)
    if not snapshot.values:
        return {"status": "not_found"}
    if not snapshot.next:
        # Double-click safe: already finished earlier!
        return {"status": "already_completed", "approved": snapshot.values.get("approved")}

    resumed = graph.invoke(Command(resume=payload), config=cfg)
    return {"status": "resumed_complete", "approved": resumed.get("approved")}

def send_approved_reply_node(state: TriageState, mailer) -> dict:
    if state.get("approved") is not True:
        raise RuntimeError("Safety guard: attempted reply dispatch without approval")
    idempotency_key = f"{state['ticket_id']}:reply:v1"
    receipt = mailer.send_reply(
        to=state["customer_email"],
        body=state["draft_reply"],
        idempotency_key=idempotency_key,
    )
    return {"trace_events": [f"email_dispatched:{receipt['message_id']}"]}

def make_scoped_order_tool(verified_tenant_id: str, db):
    # Notice `verified_tenant_id` is NOT an LLM parameter—cannot be forged by prompt injection!
    def get_tenant_order(order_id: str) -> dict:
        row = db.find_order(order_id=order_id, tenant_id=verified_tenant_id)
        if not row:
            return {"found": False}
        return {"found": True, "status": row["status"], "total_cents": row["total_cents"]}
    return get_tenant_order

from pydantic import BaseModel, Field

class PlannedStep(BaseModel):
    tool_name: str
    reason: str

class ActionPlan(BaseModel):
    steps: list[PlannedStep] = Field(min_length=1, max_length=4)

ALLOWED_PLAN_TOOLS = {"search_docs", "get_order_status", "draft_reply"}

def verify_plan(plan: ActionPlan) -> None:
    for step in plan.steps:
        if step.tool_name not in ALLOWED_PLAN_TOOLS:
            raise PermissionError(f"Blocked unpermitted planned tool: {step.tool_name}")

import time
from dataclasses import dataclass, field

@dataclass
class RunBudget:
    max_steps: int = 6
    max_total_tokens: int = 20_000
    max_seconds: float = 25.0
    started_at: float = field(default_factory=time.monotonic)
    steps: int = 0
    tokens_used: int = 0
    seen_tool_calls: set[str] = field(default_factory=set)

    def check_ok(self, proposed_call_sig: str | None = None) -> tuple[bool, str | None]:
        if self.steps >= self.max_steps:
            return False, "max_steps_reached"
        if self.tokens_used >= self.max_total_tokens:
            return False, "token_budget_exceeded"
        if (time.monotonic() - self.started_at) > self.max_seconds:
            return False, "wall_clock_timeout"
        if proposed_call_sig and proposed_call_sig in self.seen_tool_calls:
            return False, "duplicate_tool_call_loop"
        return True, None

