import re

def sanitize_untrusted_text(raw: str) -> str:
    # Strip sneaky HTML scripts/tags and limit markdown external links if displaying untrusted text
    no_tags = re.sub(r"<[^>]+>", " ", raw)
    return re.sub(r"!\[[^\]]*\]\([^)]+\)", "[image omitted]", no_tags)

def execute_proposed_refund(proposal: RefundDraft, approver_id: str | None, policy_db, stripe_client) -> dict:
    # 1-2. Deterministic business policy & ownership checks (never trust LLM alone!)
    order = policy_db.get_order(proposal.order_id)
    if not order or order["customer_email"] != proposal.customer_email:
        raise PermissionError("Order ownership check failed")
    if proposal.refund_cents > order["paid_cents"]:
        raise ValueError("Cannot refund more than paid order amount")
    # 3-4. Mandatory human approval for financial mutations
    if not approver_id:
        raise PermissionError("Human approver required before refund dispatch")
    # 5. Idempotent execution + audit log
    return stripe_client.refund(
        order_id=proposal.order_id,
        amount_cents=proposal.refund_cents,
        idempotency_key=f"refund:{proposal.order_id}:v1",
    )

