import hashlib
import hmac

def sign_callback_payload(secret: str, raw_body: bytes) -> str:
    # FastAPI signs outbound callback payload so n8n/receiver proves origin & integrity:
    return hmac.new(secret.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()

